"use client";

/**
 * The editing behaviour every text-shaped input needs.
 *
 * A number, string, date-time or JSON control cannot report every keystroke:
 * with `useSetting` that would be one request per character, and with a draft it
 * would mean validating half-typed input. So the text is held locally and
 * committed on blur or Enter, with Escape putting it back.
 */

import { useCallback, useEffect, useRef, useState, type ChangeEvent, type KeyboardEvent } from "react";

import type { ValueProblem } from "@/registry/app-settings/lib/app-settings/types";

export interface UseSettingTextOptions<T> {
  /** The committed value, from the resolution or the draft. */
  value: T;
  /** Renders the committed value as editable text. */
  format: (value: T) => string;
  /** Reads the text back. Return a problem to block the commit. */
  parse: (text: string) => { ok: true; value: T } | { ok: false; problem: ValueProblem };
  onValueChange: (value: T) => void;
  /**
   * When to report a change.
   *
   * `blur` — the default — commits when the field loses focus or Enter is
   * pressed, which is what a per-keystroke write would otherwise cost.
   * `change` commits on every keystroke, for a draft form that is saved later.
   */
  commitOn?: "blur" | "change";
  /**
   * Whether Enter commits. True by default; a textarea passes false so Enter
   * inserts a newline instead.
   */
  commitOnEnter?: boolean;
}

export interface UseSettingTextResult {
  /** What the input should display. */
  text: string;
  /** Why the current text cannot be committed. */
  problem: ValueProblem | null;
  /** The text differs from the committed value. */
  dirty: boolean;
  onChange: (event: ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => void;
  onFocus: () => void;
  onBlur: () => void;
  onKeyDown: (event: KeyboardEvent<HTMLElement>) => void;
  /** Commits the current text by hand, for a Save button inside the field. */
  commit: () => boolean;
  /** Throws the edit away and shows the committed value again. */
  revert: () => void;
}

export function useSettingText<T>({
  value,
  format,
  parse,
  onValueChange,
  commitOn = "blur",
  commitOnEnter = true,
}: UseSettingTextOptions<T>): UseSettingTextResult {
  const formatted = format(value);
  const [text, setText] = useState(formatted);
  const [problem, setProblem] = useState<ValueProblem | null>(null);
  const editing = useRef(false);

  // Follow the committed value, but never yank the text out from under someone
  // who is mid-edit — that is how a background refetch eats a keystroke.
  useEffect(() => {
    if (!editing.current) {
      setText(formatted);
      setProblem(null);
    }
  }, [formatted]);

  const commitText = useCallback(
    (candidate: string) => {
      const parsed = parse(candidate);
      if (!parsed.ok) {
        setProblem(parsed.problem);
        return false;
      }
      setProblem(null);
      if (format(parsed.value) !== formatted) onValueChange(parsed.value);
      return true;
    },
    [parse, format, formatted, onValueChange],
  );

  return {
    text,
    problem,
    dirty: text !== formatted,

    onChange: (event) => {
      setText(event.target.value);
      if (commitOn === "change") commitText(event.target.value);
    },

    onFocus: () => {
      editing.current = true;
    },

    onBlur: () => {
      editing.current = false;
      commitText(text);
    },

    onKeyDown: (event) => {
      if (event.key === "Enter" && commitOnEnter) {
        // Blurring is what commits, so a keyboard commit and a click-away
        // commit take exactly the same path.
        event.currentTarget.blur();
        return;
      }
      if (event.key === "Escape") {
        event.preventDefault();
        setText(formatted);
        setProblem(null);
      }
    },

    commit: () => commitText(text),

    revert: () => {
      setText(formatted);
      setProblem(null);
    },
  };
}

"use client";

import * as React from "react";

import type {
  SettingInputProps,
  SettingType,
  SettingValue,
} from "@/registry/app-settings/lib/app-settings/types";
import { SettingDateTimeInput } from "@/registry/app-settings/ui/app-settings/setting-datetime-input";
import { SettingJsonInput } from "@/registry/app-settings/ui/app-settings/setting-json-input";
import { SettingNumberInput } from "@/registry/app-settings/ui/app-settings/setting-number-input";
import { SettingSelect } from "@/registry/app-settings/ui/app-settings/setting-select";
import { SettingSwitch } from "@/registry/app-settings/ui/app-settings/setting-switch";
import { SettingTextInput } from "@/registry/app-settings/ui/app-settings/setting-text-input";

/** Any control that can render one setting's value. */
export type SettingInputComponent = React.ComponentType<SettingInputProps<SettingValue>>;

/**
 * The default control for each setting type.
 *
 * The casts are where the mapping is asserted: a `BOOLEAN` value is only ever
 * handed to the switch, so the switch is free to say it takes a boolean.
 */
export const settingInputs: Record<SettingType, SettingInputComponent> = {
  BOOLEAN: SettingSwitch as unknown as SettingInputComponent,
  NUMBER: SettingNumberInput as unknown as SettingInputComponent,
  STRING: SettingTextInput as unknown as SettingInputComponent,
  DATETIME: SettingDateTimeInput as unknown as SettingInputComponent,
  SELECT: SettingSelect as unknown as SettingInputComponent,
  JSON: SettingJsonInput as unknown as SettingInputComponent,
};

/** A partial override of the defaults, by setting type. */
export type SettingInputOverrides = Partial<Record<SettingType, SettingInputComponent>>;

const SettingInputsContext = React.createContext<SettingInputOverrides>({});

/**
 * Swaps the control used for one or more types, for everything below it.
 *
 * @example A slider for every bounded number on the page:
 * <SettingInputsProvider inputs={{ NUMBER: BoundedSlider }}>
 *   <SettingList />
 * </SettingInputsProvider>
 */
export function SettingInputsProvider({
  inputs,
  children,
}: {
  inputs: SettingInputOverrides;
  children?: React.ReactNode;
}) {
  const inherited = React.useContext(SettingInputsContext);
  const merged = React.useMemo(() => ({ ...inherited, ...inputs }), [inherited, inputs]);
  return <SettingInputsContext.Provider value={merged}>{children}</SettingInputsContext.Provider>;
}

/** The control registered for a type, honouring any provider above. */
export function useSettingInput(type: SettingType): SettingInputComponent {
  const overrides = React.useContext(SettingInputsContext);
  return overrides[type] ?? settingInputs[type];
}

export interface SettingInputDispatchProps extends SettingInputProps<SettingValue> {
  /** Overrides the control for this field alone. */
  as?: SettingInputComponent;
}

/**
 * Renders the right control for a setting's declared type.
 *
 * This is the seam: pass `as` for one field, wrap a subtree in
 * `<SettingInputsProvider>` for a page, or edit `settingInputs` for the whole
 * app — the file is yours once it is installed.
 */
export function SettingInput({ as, ...props }: SettingInputDispatchProps) {
  const Registered = useSettingInput(props.setting.type);
  const Control = as ?? Registered;
  return <Control {...props} />;
}

"use client";

import * as React from "react";

import { Switch } from "@/components/ui/switch";
import { cn } from "@/lib/utils";
import type {
  SettingInputComponentProps,
} from "@/registry/app-settings/lib/app-settings/types";

export type SettingSwitchProps = SettingInputComponentProps<
  boolean,
  React.ComponentProps<typeof Switch>
>;

/** The control for a `BOOLEAN` setting. */
export function SettingSwitch({
  setting,
  value,
  onValueChange,
  disabled,
  pending,
  className,
  ...props
}: SettingSwitchProps) {
  return (
    <Switch
      data-slot="setting-switch"
      data-pending={pending || undefined}
      checked={value === true}
      onCheckedChange={onValueChange}
      disabled={disabled}
      className={cn("data-[pending=true]:opacity-70", className)}
      {...props}
    />
  );
}

"use client";

import * as React from "react";

import { Input } from "@/components/ui/input";
import { cn } from "@/lib/utils";
import {
  numberStep,
  parseNumberInput,
} from "@/registry/app-settings/lib/app-settings/values";
import type {
  SettingInputComponentProps,
} from "@/registry/app-settings/lib/app-settings/types";
import { useSettingText } from "@/registry/app-settings/hooks/app-settings/use-setting-text";

export type SettingNumberInputProps = SettingInputComponentProps<
  number,
  React.ComponentProps<typeof Input>
> & {
  /** `blur` — the default — avoids a write per keystroke. */
  commitOn?: "blur" | "change";
};

/**
 * The control for a `NUMBER` setting.
 *
 * `min`, `max` and `step` come from the setting's own `type_config`, so the
 * browser's spinner respects the same bounds the server enforces.
 */
export function SettingNumberInput({
  setting,
  value,
  onValueChange,
  disabled,
  pending,
  commitOn = "blur",
  className,
  ...props
}: SettingNumberInputProps) {
  const config = setting.type_config ?? {};

  const text = useSettingText<number>({
    value,
    format: (current) => (Number.isFinite(current) ? String(current) : ""),
    parse: (raw) => {
      const parsed = parseNumberInput(raw);
      return parsed === undefined
        ? { ok: false, problem: { rule: "type", message: "Must be a number." } }
        : { ok: true, value: parsed };
    },
    onValueChange,
    commitOn,
  });

  return (
    <Input
      data-slot="setting-number-input"
      data-pending={pending || undefined}
      type="number"
      inputMode={config.integer ? "numeric" : "decimal"}
      min={config.min}
      max={config.max}
      step={numberStep(config)}
      value={text.text}
      onChange={text.onChange}
      onFocus={text.onFocus}
      onBlur={text.onBlur}
      onKeyDown={text.onKeyDown}
      disabled={disabled}
      aria-invalid={props["aria-invalid"] || text.problem !== null || undefined}
      className={cn("max-w-[12rem] font-mono tabular-nums", className)}
      {...props}
    />
  );
}

"use client";

import * as React from "react";

import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { cn } from "@/lib/utils";
import type {
  SettingInputComponentProps,
} from "@/registry/app-settings/lib/app-settings/types";
import { useSettingText } from "@/registry/app-settings/hooks/app-settings/use-setting-text";

export type SettingTextInputProps = SettingInputComponentProps<
  string,
  React.ComponentProps<typeof Input>
> & {
  /**
   * Render a textarea instead of a single-line input.
   *
   * Left unset, a setting whose `max_length` is over 120 gets one, since that
   * is rarely a value anyone wants to edit through a one-line field.
   */
  multiline?: boolean;
  rows?: number;
  commitOn?: "blur" | "change";
};

/** The control for a `STRING` setting. */
export function SettingTextInput({
  setting,
  value,
  onValueChange,
  disabled,
  pending,
  multiline,
  rows = 3,
  commitOn = "blur",
  className,
  ...props
}: SettingTextInputProps) {
  const config = setting.type_config ?? {};
  const long = multiline ?? (config.max_length !== undefined && config.max_length > 120);

  const text = useSettingText<string>({
    value,
    format: (current) => current ?? "",
    parse: (raw) => ({ ok: true, value: raw }),
    onValueChange,
    commitOn,
    commitOnEnter: !long,
  });

  const shared = {
    "data-pending": pending || undefined,
    value: text.text,
    onChange: text.onChange,
    onFocus: text.onFocus,
    onBlur: text.onBlur,
    onKeyDown: text.onKeyDown,
    disabled,
    maxLength: config.max_length,
    minLength: config.min_length,
  } as const;

  if (long) {
    return (
      <Textarea
        data-slot="setting-text-input"
        rows={rows}
        {...shared}
        className={cn("min-h-16", className)}
        {...(props as React.ComponentProps<typeof Textarea>)}
      />
    );
  }

  return (
    <Input
      data-slot="setting-text-input"
      type="text"
      // A pattern is RE2 on the server; the browser reads it as a JavaScript
      // regex, which is close enough for a hint and never the last word.
      pattern={config.pattern}
      {...shared}
      className={className}
      {...props}
    />
  );
}

"use client";

import * as React from "react";
import { localToInstant } from "app-settings-js";

import { Input } from "@/components/ui/input";
import { cn } from "@/lib/utils";
import { formatDateTimeInput } from "@/registry/app-settings/lib/app-settings/values";
import type {
  SettingInputComponentProps,
} from "@/registry/app-settings/lib/app-settings/types";
import { useSettingText } from "@/registry/app-settings/hooks/app-settings/use-setting-text";

export type SettingDateTimeInputProps = SettingInputComponentProps<
  string,
  React.ComponentProps<typeof Input>
> & {
  /**
   * The zone the reading is interpreted in. Defaults to the browser's own.
   *
   * The same wall-clock reading is a different instant in every zone, so an
   * operator setting a cutoff for a specific region should say which one.
   */
  timeZone?: string;
  commitOn?: "blur" | "change";
};

/**
 * The control for a `DATETIME` setting.
 *
 * The server stores instants and rejects a bare reading, so what the input
 * shows is the value in a timezone and what it commits is the RFC 3339 instant
 * that reading corresponds to.
 */
export function SettingDateTimeInput({
  setting,
  value,
  onValueChange,
  disabled,
  pending,
  timeZone,
  commitOn = "blur",
  className,
  ...props
}: SettingDateTimeInputProps) {
  const text = useSettingText<string>({
    value,
    format: (current) => formatDateTimeInput(current, timeZone),
    parse: (raw) => {
      if (raw.trim() === "") return { ok: true, value: "" };
      try {
        return { ok: true, value: localToInstant(raw, timeZone) };
      } catch (caught) {
        return {
          ok: false,
          problem: {
            rule: "type",
            message: caught instanceof Error ? caught.message : "Not a date and time.",
          },
        };
      }
    },
    onValueChange,
    commitOn,
  });

  return (
    <Input
      data-slot="setting-datetime-input"
      data-pending={pending || undefined}
      type="datetime-local"
      step={1}
      value={text.text}
      onChange={text.onChange}
      onFocus={text.onFocus}
      onBlur={text.onBlur}
      onKeyDown={text.onKeyDown}
      disabled={disabled}
      aria-invalid={props["aria-invalid"] || text.problem !== null || undefined}
      className={cn("max-w-[16rem]", className)}
      {...props}
    />
  );
}

"use client";

import * as React from "react";

import { Checkbox } from "@/components/ui/checkbox";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { cn } from "@/lib/utils";
import {
  asArray,
  isMultiSelect,
  optionToken,
  selectOptions,
} from "@/registry/app-settings/lib/app-settings/values";
import type {
  SettingInputProps,
  SettingValue,
} from "@/registry/app-settings/lib/app-settings/types";

export interface SettingSelectProps extends SettingInputProps<SettingValue> {
  placeholder?: string;
  /** Forwarded to the trigger, for width or a `data-*` attribute. */
  triggerProps?: React.ComponentProps<typeof SelectTrigger>;
}

/**
 * The control for a `SELECT` setting.
 *
 * A single-choice setting gets a select; a `multiple` one gets a checkbox
 * list, because a multi-select popover hides what is chosen behind a click and
 * a settings board exists to show exactly that.
 *
 * Option values need not be strings — the server allows numbers and booleans —
 * so each option carries a string token for the DOM and the real value is
 * recovered from it on change.
 */
export function SettingSelect({
  setting,
  value,
  onValueChange,
  disabled,
  pending,
  id,
  className,
  placeholder = "Choose…",
  triggerProps,
  ...props
}: SettingSelectProps) {
  const options = selectOptions(setting);

  if (isMultiSelect(setting)) {
    const chosen = new Set(asArray(value).map(optionToken));

    return (
      <div
        data-slot="setting-select"
        data-multiple
        data-pending={pending || undefined}
        role="group"
        aria-labelledby={id}
        className={cn("flex flex-col gap-2", className)}
        {...props}
      >
        {options.map((option) => {
          const optionId = `${id ?? setting.name}-${option.token}`;
          return (
            <div key={option.token} className="flex items-center gap-2">
              <Checkbox
                id={optionId}
                checked={chosen.has(option.token)}
                disabled={disabled}
                onCheckedChange={(checked) => {
                  const next = options
                    .filter((candidate) =>
                      candidate.token === option.token
                        ? checked === true
                        : chosen.has(candidate.token),
                    )
                    .map((candidate) => candidate.value);
                  onValueChange(next);
                }}
              />
              <Label htmlFor={optionId} className="text-sm font-normal">
                {option.label}
              </Label>
            </div>
          );
        })}
      </div>
    );
  }

  const current = value === null || value === undefined ? undefined : optionToken(value);

  return (
    <Select
      value={current}
      disabled={disabled}
      onValueChange={(token) => {
        const option = options.find((candidate) => candidate.token === token);
        if (option) onValueChange(option.value);
      }}
    >
      <SelectTrigger
        data-slot="setting-select"
        data-pending={pending || undefined}
        id={id}
        aria-describedby={props["aria-describedby"]}
        aria-invalid={props["aria-invalid"]}
        className={cn("max-w-[16rem]", className)}
        {...triggerProps}
      >
        <SelectValue placeholder={placeholder} />
      </SelectTrigger>
      <SelectContent>
        {options.map((option) => (
          <SelectItem key={option.token} value={option.token}>
            {option.label}
          </SelectItem>
        ))}
      </SelectContent>
    </Select>
  );
}

"use client";

import * as React from "react";

import { Textarea } from "@/components/ui/textarea";
import { cn } from "@/lib/utils";
import {
  formatJsonInput,
  parseJsonInput,
} from "@/registry/app-settings/lib/app-settings/values";
import type {
  SettingInputComponentProps,
  SettingValue,
} from "@/registry/app-settings/lib/app-settings/types";
import { useSettingText } from "@/registry/app-settings/hooks/app-settings/use-setting-text";

export type SettingJsonInputProps = SettingInputComponentProps<
  SettingValue,
  React.ComponentProps<typeof Textarea>
> & {
  rows?: number;
  commitOn?: "blur" | "change";
};

/**
 * The control for a `JSON` setting.
 *
 * The parser's own complaint is shown under the field, and nothing is committed
 * while the text is not JSON — so a half-typed object cannot be saved.
 */
export function SettingJsonInput({
  setting,
  value,
  onValueChange,
  disabled,
  pending,
  rows = 6,
  commitOn = "blur",
  className,
  ...props
}: SettingJsonInputProps) {
  const text = useSettingText<SettingValue>({
    value,
    format: formatJsonInput,
    parse: (raw) => {
      const parsed = parseJsonInput(raw);
      return parsed.ok
        ? { ok: true, value: parsed.value }
        : { ok: false, problem: parsed.problem };
    },
    onValueChange,
    commitOn,
    commitOnEnter: false,
  });

  return (
    <div className="flex w-full flex-col gap-1.5">
      <Textarea
        data-slot="setting-json-input"
        data-pending={pending || undefined}
        spellCheck={false}
        rows={rows}
        value={text.text}
        onChange={text.onChange}
        onFocus={text.onFocus}
        onBlur={text.onBlur}
        onKeyDown={text.onKeyDown}
        disabled={disabled}
        aria-invalid={props["aria-invalid"] || text.problem !== null || undefined}
        className={cn("font-mono text-xs", className)}
        {...props}
      />
      {text.problem && (
        <p className="text-destructive text-xs" role="alert">
          {text.problem.message}
        </p>
      )}
    </div>
  );
}
